examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchAiStarterPrompts(
        prompts = listOf(
            MonarchAiStarterPrompt({{prompts.0.id}}, {{prompts.0.title}}, {{prompts.0.prompt}}),
            MonarchAiStarterPrompt({{prompts.1.id}}, {{prompts.1.title}}, {{prompts.1.prompt}}),
            MonarchAiStarterPrompt({{prompts.2.id}}, {{prompts.2.title}}, {{prompts.2.prompt}}),
            MonarchAiStarterPrompt({{prompts.3.id}}, {{prompts.3.title}}, {{prompts.3.prompt}}),
        ),
        onSelect = {},
        layout = MonarchAiStarterPromptsLayout.{{layout|pascal}},
    )
    MonarchText(text = "Choose a prompt.", style = MonarchTextStyle.Caption)
}

examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchAiStarterPrompts(
        prompts = listOf(
            MonarchAiStarterPrompt("summary", "Summarise a document", "Summarise the open document in five bullet points."),
            MonarchAiStarterPrompt("reply", "Draft a reply", "Draft a short, friendly reply to the latest message."),
            MonarchAiStarterPrompt("plan", "Plan the week", "Turn my open tasks into a plan for this week."),
            MonarchAiStarterPrompt("explain", "Explain a chart", "Explain what the chart on this page shows and what stands out."),
        ),
        onSelect = {},
        layout = MonarchAiStarterPromptsLayout.Grid,
    )
    MonarchText(text = "Choose a prompt.", style = MonarchTextStyle.Caption)
}
